class ValidationTimeWindowPeriod(pycarlo.lib.types.Enum):
    """Rolling-window period for a validation monitor's time filter. Each
    value maps to a fixed number of hours evaluated relative to run
    start time: - `PAST_HOUR` = 1 hour - `PAST_1_DAY` = 24 hours -
    `PAST_2_DAYS` = 48 hours - `PAST_3_DAYS` = 72 hours -
    `PAST_5_DAYS` = 120 hours - `PAST_1_WEEK` = 168 hours -
    `PAST_2_WEEKS` = 336 hours - `PAST_3_WEEKS` = 504 hours -
    `PAST_4_WEEKS` = 672 hours

    Enumeration Choices:

    * `PAST_1_DAY`None
    * `PAST_1_WEEK`None
    * `PAST_2_DAYS`None
    * `PAST_2_WEEKS`None
    * `PAST_3_DAYS`None
    * `PAST_3_WEEKS`None
    * `PAST_4_WEEKS`None
    * `PAST_5_DAYS`None
    * `PAST_HOUR`None
    """

    __schema__ = schema
    __choices__ = (
        "PAST_1_DAY",
        "PAST_1_WEEK",
        "PAST_2_DAYS",
        "PAST_2_WEEKS",
        "PAST_3_DAYS",
        "PAST_3_WEEKS",
        "PAST_4_WEEKS",
        "PAST_5_DAYS",
        "PAST_HOUR",
    )


