class ConversationFiltersInput(sgqlc.types.Input):
    """Filters for the getConversations query."""

    __schema__ = schema
    __field_names__ = (
        "conversation_id_search",
        "trace_id",
        "workflows",
        "statuses",
        "has_errors",
        "min_turns",
        "max_turns",
        "min_total_tokens",
        "max_total_tokens",
        "min_duration",
        "max_duration",
        "min_active_duration",
        "max_active_duration",
        "cluster_keys",
        "run_uuid",
    )
    conversation_id_search = sgqlc.types.Field(String, graphql_name="conversationIdSearch")
    """Case-insensitive substring search on conversation_id"""

    trace_id = sgqlc.types.Field(String, graphql_name="traceId")
    """Filter by exact trace ID (hex-encoded) — returns the conversation
    that contains this trace
    """

    workflows = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(String)), graphql_name="workflows"
    )
    """Filter by workflow names (OR logic). Empty or omitted returns all."""

    statuses = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(ConversationStatus)), graphql_name="statuses"
    )
    """Filter by status (ERROR, OK). Empty or omitted returns all."""

    has_errors = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(HasErrorsValue)), graphql_name="hasErrors"
    )
    """Filter by presence of erroring spans across the conversation's
    traces (excluding LangGraph GraphInterrupt sentinels). Values:
    'OK' or 'HAS_ERRORS' (OR logic). Empty or omitted returns all.
    Composes with `statuses` — e.g. statuses=[OK] AND
    hasErrors=[HAS_ERRORS] surfaces conversations that completed
    cleanly but had retried/recovered errors along the way.
    """

    min_turns = sgqlc.types.Field(Int, graphql_name="minTurns")
    """Minimum number of turns (inclusive)"""

    max_turns = sgqlc.types.Field(Int, graphql_name="maxTurns")
    """Maximum number of turns (inclusive)"""

    min_total_tokens = sgqlc.types.Field(Int, graphql_name="minTotalTokens")
    """Minimum total tokens (inclusive)"""

    max_total_tokens = sgqlc.types.Field(Int, graphql_name="maxTotalTokens")
    """Maximum total tokens (inclusive)"""

    min_duration = sgqlc.types.Field(Float, graphql_name="minDuration")
    """Minimum conversation duration in seconds"""

    max_duration = sgqlc.types.Field(Float, graphql_name="maxDuration")
    """Maximum conversation duration in seconds"""

    min_active_duration = sgqlc.types.Field(Float, graphql_name="minActiveDuration")
    """Minimum active (processing) duration in seconds — sum of per-turn
    processing time, excluding idle gaps between turns
    """

    max_active_duration = sgqlc.types.Field(Float, graphql_name="maxActiveDuration")
    """Maximum active (processing) duration in seconds — sum of per-turn
    processing time, excluding idle gaps between turns
    """

    cluster_keys = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(String)), graphql_name="clusterKeys"
    )
    """Filter the list to conversations assigned to these clusters
    (within the query's clusteringSpaceUuid — intent or issue facet).
    Empty or omitted applies no cluster filter; requires
    clusteringSpaceUuid to be set.
    """

    run_uuid = sgqlc.types.Field(UUID, graphql_name="runUuid")
    """Filter to the conversations evaluated in a monitor run: pass an
    agent evaluation monitor run's jobExecutionUuid (as surfaced on
    monitor chart datapoints) to keep only conversations that were
    scored in that run. Combines (ANDs) with the other filters. Only
    conversation-aggregation agent evaluation runs carry per-
    conversation score linkage: span-scored runs return an empty page,
    and trace-aggregation runs are rejected, as are runs that
    evaluated more than 500 conversations (rather than returning an
    incomplete list). startTime/endTime still bound the span scan —
    pass a window generously covering the run's period so boundary
    conversations aggregate completely.
    """


