class CreateOrUpdateConversationClusteringSpaceInput(sgqlc.types.Input):
    __schema__ = schema
    __field_names__ = (
        "space_uuid",
        "agent_name",
        "trace_table_mcon",
        "scope_workflow",
        "facet",
        "is_enabled",
        "user_guidance",
        "config_overrides",
    )
    space_uuid = sgqlc.types.Field(UUID, graphql_name="spaceUuid")
    """Set to update an existing space; null to create."""

    agent_name = sgqlc.types.Field(String, graphql_name="agentName")
    """Required on create; immutable on update."""

    trace_table_mcon = sgqlc.types.Field(String, graphql_name="traceTableMcon")
    """Required on create; immutable on update."""

    scope_workflow = sgqlc.types.Field(String, graphql_name="scopeWorkflow")
    """Null = whole agent; set on create, immutable."""

    facet = sgqlc.types.Field(ClusteringFacet, graphql_name="facet")
    """On create: which facet to create. Omit to opt in to both an intent
    and an issue space for the scope in one call — the enablement
    toggle's shape. configOverrides and userGuidance then land on the
    intent space only; the issue space is created with its facet
    defaults — tune its cadence or percentile window with a follow-up
    update against its own uuid, the same way pause already works. Set
    explicitly to create only that facet's space. On update: immutable
    — must match the target space's facet.
    """

    is_enabled = sgqlc.types.Field(Boolean, graphql_name="isEnabled")
    """Pause (false) / resume (true) an existing space. On the create-
    both opt-in (facet omitted, no spaceUuid), applies to both spaces.
    """

    user_guidance = sgqlc.types.Field(String, graphql_name="userGuidance")
    """Free-text guidance that steers cluster identity during discovery;
    rejected on an issue-facet space, which has no discovery step. On
    the create-both opt-in, applies to the intent space only.
    """

    config_overrides = sgqlc.types.Field(ClusteringConfigInput, graphql_name="configOverrides")
    """Partial config overrides applied on top of the current settings.
    On the create-both opt-in, applies to the intent space only.
    """


class CreateOrUpdateCustomConversationClusterInput(sgqlc.types.Input):
    __schema__ = schema
    __field_names__ = ("space_uuid", "cluster_uuid", "name", "description")
    space_uuid = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="spaceUuid")
    """The cluster's intent-facet space. On create, the space to add the
    cluster to; on update, it must match the target cluster's space —
    a mismatch reads as an unknown cluster.
    """

    cluster_uuid = sgqlc.types.Field(UUID, graphql_name="clusterUuid")
    """Set to update an existing custom cluster; null to create one."""

    name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="name")
    """Display name. On create it also derives the stable cluster key;
    renaming later never changes the key, so trends survive a rename.
    """

    description = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="description")
    """What belongs in this cluster — shown on the card and used verbatim
    as the classification criteria, so write it for the classifier.
    """


class CreateOrUpdatePlatformAgentInput(sgqlc.types.Input):
    __schema__ = schema
    __field_names__ = (
        "warehouse_uuid",
        "agent_name",
        "agent_database",
        "agent_schema",
        "connection_uuid",
        "domain_uuid",
        "platform_agent_type",
        "table_prefix",
    )
    warehouse_uuid = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="warehouseUuid")
    """Warehouse UUID"""

    agent_name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentName")
    """Agent name on the platform"""

    agent_database = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentDatabase")
    """Platform database containing the agent. For Databricks platform
    agents this is the Unity Catalog catalog name.
    """

    agent_schema = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentSchema")
    """Platform schema containing the agent. For Databricks platform
    agents this is the Unity Catalog schema name.
    """

    connection_uuid = sgqlc.types.Field(UUID, graphql_name="connectionUuid")
    """Connection UUID (optional, defaults to the warehouse's SQL query
    connection)
    """

    domain_uuid = sgqlc.types.Field(UUID, graphql_name="domainUuid")
    """Domain to assign a Snowflake agent to (may be required for
    accounts using domain-based access). Not accepted for Databricks
    agents — their domains derive from the trace table's catalog
    domain assignments.
    """

    platform_agent_type = sgqlc.types.Field(PlatformAgentType, graphql_name="platformAgentType")
    """Platform agent integration type. Defaults to SNOWFLAKE when
    omitted, preserving backwards compatibility for Snowflake callers.
    Databricks Agent Bricks splits into two physical span shapes:
    DATABRICKS_MLFLOW_SDK (Mosaic AI Agent Framework + autolog) and
    DATABRICKS_MLFLOW_KA (Knowledge Assistant UI sync). The SDK and KA
    shapes differ on disk, so registration resolves the subtype from
    the trace table's physical shape — overriding the supplied value,
    and rejecting a fresh registration when the shape can't be
    resolved to exactly one of the two.
    """

    table_prefix = sgqlc.types.Field(String, graphql_name="tablePrefix")
    """Trace-table identifier prefix; required for Databricks platform
    agents, ignored for Snowflake. For DATABRICKS_MLFLOW_SDK the SDK
    exposes a `<table_prefix>_trace_unified` view (over
    `<table_prefix>_otel_*` managed tables); for DATABRICKS_MLFLOW_KA
    the table_prefix IS the Delta table name.
    """


