class SelfHostedCredentialsConnectionDetails(sgqlc.types.Input):
    __schema__ = schema
    __field_names__ = (
        "connection_type",
        "self_hosted_credentials_type",
        "decryption_service_type",
        "env_var_name",
        "kms_key_id",
        "aws_secret",
        "gcp_secret",
        "akv_vault_name",
        "akv_vault_url",
        "akv_secret",
        "file_path",
        "aws_region",
        "assumable_role",
        "external_id",
        "bq_project_id",
        "databricks_warehouse_id",
    )
