class TraceFiltersInput(sgqlc.types.Input):
    """Optional filters to refine trace results within the time range."""

    __schema__ = schema
    __field_names__ = (
        "models",
        "workflows",
        "tasks",
        "tools",
        "min_duration",
        "max_duration",
        "min_prompt_tokens",
        "max_prompt_tokens",
        "min_completion_tokens",
        "max_completion_tokens",
        "min_total_tokens",
        "max_total_tokens",
        "conversation_id",
        "trace_id",
        "statuses",
        "root_statuses",
        "search_query",
        "run_uuid",
    )
    models = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(String)), graphql_name="models"
    )
    """Filter by model names (OR logic)"""

    workflows = sgqlc.types.Field(sgqlc.types.list_of(String), graphql_name="workflows")
    """Filter by workflow names (OR logic). A null element selects the
    no-workflow scope — traces whose spans carry no workflow label.
    """

    tasks = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(String)), graphql_name="tasks"
    )
    """Filter by task names (OR logic)"""

    tools = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(String)), graphql_name="tools"
    )
    """Filter to traces containing at least one tool-call span whose tool
    name matches (OR logic). Tool names are bare, without the
    Traceloop '.tool' suffix — matching the values surfaced by
    getTopTools.
    """

    min_duration = sgqlc.types.Field(Float, graphql_name="minDuration")
    """Minimum duration in seconds"""

    max_duration = sgqlc.types.Field(Float, graphql_name="maxDuration")
    """Maximum duration in seconds"""

    min_prompt_tokens = sgqlc.types.Field(Int, graphql_name="minPromptTokens")
    """Minimum prompt tokens"""

    max_prompt_tokens = sgqlc.types.Field(Int, graphql_name="maxPromptTokens")
    """Maximum prompt tokens"""

    min_completion_tokens = sgqlc.types.Field(Int, graphql_name="minCompletionTokens")
    """Minimum completion tokens"""

    max_completion_tokens = sgqlc.types.Field(Int, graphql_name="maxCompletionTokens")
    """Maximum completion tokens"""

    min_total_tokens = sgqlc.types.Field(Int, graphql_name="minTotalTokens")
    """Minimum total tokens"""

    max_total_tokens = sgqlc.types.Field(Int, graphql_name="maxTotalTokens")
    """Maximum total tokens"""

    conversation_id = sgqlc.types.Field(String, graphql_name="conversationId")
    """Filter by exact conversation ID"""

    trace_id = sgqlc.types.Field(String, graphql_name="traceId")
    """Filter by exact trace ID (hex-encoded)"""

    statuses = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(String)), graphql_name="statuses"
    )
    """Filter by presence of any erroring span (any-span semantic — *not*
    root-span). Values: 'OK' or 'HAS_ERRORS' (OR logic).
    GraphInterrupt sentinels are excluded. Empty or omitted returns
    all. See also rootStatuses for root-span-level filtering. Note:
    this field's name mirrors ConversationFiltersInput.statuses but
    carries different semantics (any-span here, root-span there); the
    inversion is preserved for backwards compatibility (see AO-560 for
    the planned rename to hasErrors).
    """

    root_statuses = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(TraceRootStatus)), graphql_name="rootStatuses"
    )
    """Filter by root-span status: 'OK' or 'ERROR' (OR logic).
    GraphInterrupt sentinels are excluded. Empty or omitted returns
    all. Composes with `statuses` — e.g. rootStatuses=[OK] AND
    statuses=[HAS_ERRORS] surfaces traces that completed cleanly but
    had retried/recovered span errors along the way.
    """

    search_query = sgqlc.types.Field(String, graphql_name="searchQuery")
    """Filter by custom span-attribute metadata. Syntax: `key:value` for
    exact match; `-key:value` to exclude; quote multi-word values
    (`key:"two words"`); space-separated clauses combine with AND.
    Bare keys (no dot) are looked up under the standard custom-
    metadata namespace; dotted keys are matched as-is. Only available
    on accounts whose trace data is served from ClickHouse.
    """

    run_uuid = sgqlc.types.Field(UUID, graphql_name="runUuid")
    """Filter to the traces evaluated in a monitor run: pass an agent
    evaluation monitor run's jobExecutionUuid (as surfaced on monitor
    chart datapoints) to keep only traces that produced at least one
    scored row in that run. Combines (ANDs) with the other filters.
    Exact run membership is available only for AO-managed ClickHouse
    agent evaluation monitors. Runs of other monitor types are
    rejected, as are trace-aggregation agent evaluation runs (their
    scores carry no per-row trace linkage) and runs that evaluated
    more than 10,000 traces (rather than returning an incomplete
    list). Runs of conversation-scored monitors carry no trace linkage
    and return an empty page.
    """


