class TriageAlertsInput(sgqlc.types.Input):
    __schema__ = schema
    __field_names__ = (
        "incident_ids",
        "source",
        "feed_search_params",
        "post_to_slack",
        "trigger_source",
    )
    incident_ids = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(UUID))),
        graphql_name="incidentIds",
    )
    """UUIDs of incidents to triage. Maximum 50 per call."""

    source = sgqlc.types.Field(TriageBatchSource, graphql_name="source")
    """Where the triage was initiated from. Drives the deep-link target
    of the completion notification — ``ALERT`` lands the user on the
    alert detail page, ``FEED`` restores the alerts-feed cohort the
    user submitted from. Optional for backward compatibility with
    older clients; defaults to ``FEED`` server-side when omitted,
    which matches the historical caller (the alerts feed).
    """

    feed_search_params = sgqlc.types.Field(String, graphql_name="feedSearchParams")
    """Serialized URL search params from the alerts feed at submit time,
    used to reconstruct the original cohort when the completion
    notification is clicked. Only meaningful when ``source == FEED``;
    ignored otherwise. Capped at 2048 characters.
    """

    post_to_slack = sgqlc.types.Field(Boolean, graphql_name="postToSlack")
    """Whether to post the triage summary as a Slack thread reply on the
    alert message when the run completes. Defaults to true. Pass false
    when the caller already shows the verdict to the user (e.g. the
    chat agent running in the Slack bot) so the summary isn't
    duplicated. Does NOT affect the alert message's own triage state —
    the in-progress status, completed priority dot, and Triage-button
    removal always sync — nor the in-product completion notification.
    """

    trigger_source = sgqlc.types.Field(TriageTriggerSource, graphql_name="triggerSource")
    """The surface this triage was dispatched from, recorded on the per-
    incident triage claim (usage accounting / analytics). Programmatic
    callers should declare themselves (MCP for the MCP triage tool,
    SLACK for the chat agent in the Slack bot). When omitted,
    resolution is: the surface the client names in its x-mcd-source
    request header (dashboard resolves to MANUAL_UI, mcp to MCP);
    otherwise SLACK if postToSlack is false (today's only such caller
    is the Slack-bot chat agent); otherwise MANUAL_UI.
    """


