    entities = sgqlc.types.Field(sgqlc.types.list_of(String), graphql_name="entities")
    """Full table IDs for monitored tables/views"""

    entity_mcons = sgqlc.types.Field(sgqlc.types.list_of(String), graphql_name="entityMcons")
