    tags = sgqlc.types.Field(sgqlc.types.list_of("TagKeyValuePairOutput"), graphql_name="tags")
    """Tags on this monitor."""

    data_quality_dimension = sgqlc.types.Field(String, graphql_name="dataQualityDimension")
    """Data quality dimension on a monitor."""

    domain_uuids = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(UUID)), graphql_name="domainUuids"
    )
    """Domain UUIDs assigned to the monitor."""

    domains = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null("DomainOutput")), graphql_name="domains"
    )
    """Domains assigned to the monitor, resolved to full domain objects."""

    is_ootb_replacement = sgqlc.types.Field(Boolean, graphql_name="isOotbReplacement")
    """(experimental) Returns if this monitor replaces the default ootb
    detector.
    """

    timeout = sgqlc.types.Field(Int, graphql_name="timeout")
    """Timeout for the SQL query"""

    is_agent_trace_aggregation = sgqlc.types.Field(Boolean, graphql_name="isAgentTraceAggregation")
    """If True, aggregate spans by trace_id for agent metric monitors."""

    is_agent_conversation_aggregation = sgqlc.types.Field(
        Boolean, graphql_name="isAgentConversationAggregation"
    )
    """If True, the monitor operates at the conversation grain — eval
    monitors score whole conversations, metric monitors compute
    conversation-level metrics; if False, it operates on individual
    spans. Null for non-agent monitors (or legacy monitors predating
    the field).
    """

    dashboards = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null("MonitorDashboard")), graphql_name="dashboards"
    )
    """Dashboards sourced from the monitor."""

    is_hidden_for_asset = sgqlc.types.Field(Boolean, graphql_name="isHiddenForAsset")
    """(experimental) Whether this monitor is hidden when viewing it in
    the context of a specific asset. Only meaningful when monitors are
    queried with a single mcon filter. Defaults to False.
    """

    agent_mcon = sgqlc.types.Field(String, graphql_name="agentMcon")
    """MCON identifying the platform agent, if this is a platform agent
    monitor.
    """

    agent = sgqlc.types.Field(String, graphql_name="agent")
    """Name of the monitored agent for agent monitors (metric,
    evaluation, trajectory, validation), resolved from the monitor's
    agent span scope. Null when the monitor is not agent-scoped or has
    no agent filter (e.g. it scopes only by task or span).
    """

    is_auto_created = sgqlc.types.Field(Boolean, graphql_name="isAutoCreated")
    """Whether this monitor was auto-created by monitor recommendations.
    Recommendations are no longer generated, so this identifies only
    monitors created while that feature was active.
    """

    missing_required_fields = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(RequiredMonitorField)),
        graphql_name="missingRequiredFields",
    )
    """Fields this account requires that the monitor leaves empty. Empty
    when the monitor conforms, and always empty when the account
    requires no fields.
    """


