class AgentMetadataV2(sgqlc.types.Type):
    """Metadata about AI agents for agent observability (v2 — includes
    platform agents).
    """

    __schema__ = schema
    __field_names__ = (
        "account_uuid",
        "agent_name",
        "display_name",
        "trace_table_mcon",
        "source_type",
        "agent_reference",
        "warehouse",
        "classification",
    )
    account_uuid = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="accountUuid")
    """Account UUID"""

    agent_name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentName")
    """Name of the agent"""

    display_name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="displayName")
    """Human-friendly name to show for the agent — the Databricks Agent
    Bricks tile name for Knowledge-Assistant agents. Falls back to
    `agentName` when no friendly name is stored (SDK / Snowflake
    agents and user-managed trace tables), so it is always safe to
    display directly.
    """

    trace_table_mcon = sgqlc.types.Field(
        sgqlc.types.non_null(String), graphql_name="traceTableMcon"
    )
    """MCON of the trace table or platform agent"""

    source_type = sgqlc.types.Field(
        sgqlc.types.non_null(AgentSourceType), graphql_name="sourceType"
    )
    """Source type: TRACE_TABLE for user-managed trace tables,
    PLATFORM_AGENT for platform agents
    """

    agent_reference = sgqlc.types.Field(String, graphql_name="agentReference")
    """The value to pass as the `agent` field of the
    createOrUpdateAgent*MonitorFromDefinition mutations. For a
    PLATFORM_AGENT this is the portable `{database}:{schema}.{name}`
    reference; for a TRACE_TABLE (OTel) agent it is the
    `service_name`, which equals `agentName`. Null only when a
    platform agent's registration could not be resolved.
    """

    warehouse = sgqlc.types.Field("Warehouse", graphql_name="warehouse")
    """Warehouse (resource) that owns this agent's trace table or
    platform-agent registration. Pass its `uuid` (or `name`) as the
    required `warehouse` argument of the
    createOrUpdateAgent*MonitorFromDefinition mutations — no separate
    warehouse lookup or trace-table MCON parsing needed. Null when the
    agent's warehouse association cannot be resolved (e.g. the
    warehouse was deleted).
    """

    classification = sgqlc.types.Field(AgentClassificationOutput, graphql_name="classification")
    """AI-590/AI-598 classification of this agent — same builder and
    identical lowercase wire values as the incident-keyed TSA REST
    `agent` object and `getAgentClassification`, so consumers share
    one parser across surfaces (AO-891). Note the intentional casing
    split with this node's legacy `sourceType` enum (uppercase member
    names). Null only when a platform agent's registration could not
    be resolved (same contract as `agentReference`).
    """


