class Conversation(sgqlc.types.Type):
    """A conversation groups one or more agent traces sharing the same
    conversation_id.
    """

    __schema__ = schema
    __field_names__ = (
        "conversation_id",
        "turns",
        "total_tokens",
        "start_time",
        "end_time",
        "duration_seconds",
        "active_duration_seconds",
        "status",
        "errors_count",
        "workflows",
        "eval_scores",
        "intent_cluster",
        "cluster_assignments",
    )
    conversation_id = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="conversationId")
    """Conversation identifier"""

    turns = sgqlc.types.Field(sgqlc.types.non_null(Int), graphql_name="turns")
    """Number of traces (runs) in this conversation"""

    total_tokens = sgqlc.types.Field(Int, graphql_name="totalTokens")
    """Sum of tokens across all traces in the conversation"""

    start_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="startTime")
    """Earliest trace start time in the conversation"""

    end_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="endTime")
    """Latest trace end time in the conversation"""

    duration_seconds = sgqlc.types.Field(
        sgqlc.types.non_null(Float), graphql_name="durationSeconds"
    )
    """Total conversation duration in seconds (end_time - start_time)"""

    active_duration_seconds = sgqlc.types.Field(
        sgqlc.types.non_null(Float), graphql_name="activeDurationSeconds"
    )
    """Sum of each trace's duration in seconds across the conversation,
    excluding idle gaps between traces. May exceed durationSeconds
    when traces overlap within the same conversation.
    """

    status = sgqlc.types.Field(sgqlc.types.non_null(ConversationStatus), graphql_name="status")
    """ERROR if any trace had a root span error, otherwise OK"""

    errors_count = sgqlc.types.Field(sgqlc.types.non_null(Int), graphql_name="errorsCount")
    """Number of spans across all traces in this conversation that
    errored (excluding LangGraph GraphInterrupt sentinels).
    """

    workflows = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(String))),
        graphql_name="workflows",
    )
    """Distinct workflow names across all traces in this conversation.
    Empty when none of the conversation's spans carry a workflow.
    """

    eval_scores = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null("ConversationEvalScore"))),
        graphql_name="evalScores",
    )
    """Latest stored eval score per (monitor, dimension) for this
    conversation. Empty when the conversation has not been scored by
    any conversation eval monitor.
    """

    intent_cluster = sgqlc.types.Field(ClusterAssignmentType, graphql_name="intentCluster")
    """Deprecated in favor of clusterAssignments. The conversation's
    assignment for the requested clustering scope, on a space that
    carries at most one assignment per conversation (e.g. intent) —
    the single-assignment convenience for such a space. On a space
    that can carry several assignments, this field is the highest-
    confidence one. Null when the conversation is unclassified or no
    clustering scope was requested.
    """

    cluster_assignments = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(ClusterAssignmentType))),
        graphql_name="clusterAssignments",
    )
    """Every assignment from the conversation's most recent
    classification run in the requested clustering scope, ordered
    highest-confidence first. Empty when the conversation is
    unclassified or no clustering scope was requested.
    """


