class ConversationClusterStat(sgqlc.types.Type):
    """A cluster's windowed share of classified conversations (panel
    card).
    """

    __schema__ = schema
    __field_names__ = (
        "cluster_key",
        "name",
        "description",
        "ordinal",
        "source",
        "conversation_count",
        "share_pct",
        "condition",
        "rule",
        "metrics",
    )
    cluster_key = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="clusterKey")
    """Stable cluster slug."""

    name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="name")
    """Human-readable cluster name."""

    description = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="description")
    """One-line summary of what belongs in this cluster."""

    ordinal = sgqlc.types.Field(sgqlc.types.non_null(Int), graphql_name="ordinal")
    """Position within the cluster's source group — custom (USER) and
    discovered (AUTO) clusters carry independent sequences, so values
    repeat across groups. The list order (custom first, then
    discovered, Uncategorized last) is authoritative; don't re-sort by
    this field alone.
    """

    source = sgqlc.types.Field(sgqlc.types.non_null(ClusterSource), graphql_name="source")
    """Where this cluster came from. USER marks a custom (user-defined)
    cluster — pinned before discovered clusters and stable across
    taxonomy refreshes.
    """

    conversation_count = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="conversationCount"
    )
    """Conversations assigned to this cluster in the window."""

    share_pct = sgqlc.types.Field(sgqlc.types.non_null(Float), graphql_name="sharePct")
    """Percent of classified conversations carrying this cluster's
    assignment. A conversation can carry more than one assignment, so
    cards can overlap and shares are not guaranteed to sum to 100.
    """

    condition = sgqlc.types.Field("FilterGroup", graphql_name="condition")
    """The cluster's criteria as a filter tree — the payload the ops-
    agent hand-off carries. For an eval-monitor- or percentile-derived
    cluster this may hold a marker-bearing FilterSql or literal rather
    than an executable predicate. Null on LLM-derived clusters.
    """

    rule = sgqlc.types.Field(String, graphql_name="rule")
    """The cluster's membership criteria rendered for display, e.g.
    "duration_seconds greater than 42.0" for a plain-threshold rule
    cluster. An eval-monitor-derived cluster renders the literal
    "[custom SQL condition]" instead of a readable rule, and a
    percentile-derived cluster renders its still-unresolved marker
    rather than the resolved threshold. Null on LLM-derived clusters.
    """

    metrics = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(ConversationClusterMetric))),
        graphql_name="metrics",
    )
    """The requested aggregates for this cluster's conversations in the
    window. Empty when no metrics were requested, and when the cluster
    has no conversations in the window.
    """


class ConversationClusterType(sgqlc.types.Type):
    """One cluster in a space's current taxonomy version."""

    __schema__ = schema
    __field_names__ = (
        "uuid",
        "cluster_key",
        "name",
        "description",
        "classification_criteria",
        "exemplars",
        "ordinal",
        "taxonomy_version",
        "derivation",
        "source",
        "created_by",
        "rule",
        "condition",
        "source_monitor_uuid",
    )
    uuid = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="uuid")
    """Stable cluster id."""

    cluster_key = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="clusterKey")
    """Stable slug; the join key for per-conversation assignments."""

    name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="name")
    """Human-readable cluster name."""

    description = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="description")
    """One-line summary of what belongs in this cluster."""

    classification_criteria = sgqlc.types.Field(
        sgqlc.types.non_null(String), graphql_name="classificationCriteria"
    )
    """What belongs in this cluster and how it differs from its siblings."""

    exemplars = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(String))),
        graphql_name="exemplars",
    )
    """Representative user asks for this cluster. Empty when data
    sampling is disabled for the owning warehouse or the caller lacks
    raw-data access.
    """

    ordinal = sgqlc.types.Field(sgqlc.types.non_null(Int), graphql_name="ordinal")
    """Position within the cluster's source group — custom (USER) and
    discovered (AUTO) clusters carry independent sequences, so values
    repeat across groups. The connection's order (custom first, then
    discovered) is authoritative; don't re-sort by this field alone.
    """

    taxonomy_version = sgqlc.types.Field(sgqlc.types.non_null(Int), graphql_name="taxonomyVersion")
    """Taxonomy version this cluster belongs to."""

    derivation = sgqlc.types.Field(
        sgqlc.types.non_null(ClusteringDerivation), graphql_name="derivation"
    )
    """How membership is computed: LLM classification or FilterGroup SQL."""

    source = sgqlc.types.Field(sgqlc.types.non_null(ClusterSource), graphql_name="source")
    """Where this cluster came from. USER marks a custom (user-defined)
    cluster — pinned before discovered clusters and stable across
    taxonomy refreshes.
    """

    created_by = sgqlc.types.Field(String, graphql_name="createdBy")
    """Display label for the user who created this cluster. Returns the
    user's email for human users; for agent users, returns a derived
    display label (e.g. ``Agent on <domain>``) — never the agent's
    internal address. Null on discovered clusters.
    """

    rule = sgqlc.types.Field(String, graphql_name="rule")
    """The cluster's membership criteria rendered for display, e.g.
    "duration_seconds greater than 42.0" for a plain-threshold rule
    cluster. An eval-monitor-derived cluster renders the literal
    "[custom SQL condition]" instead of a readable rule, and a
    percentile-derived cluster renders its still-unresolved marker
    rather than the resolved threshold. Null on LLM-derived clusters.
    """

    condition = sgqlc.types.Field("FilterGroup", graphql_name="condition")
    """The cluster's criteria as a filter tree — the payload the ops-
    agent hand-off carries. For an eval-monitor- or percentile-derived
    cluster this may hold a marker-bearing FilterSql or literal rather
    than an executable predicate. Null on LLM-derived clusters.
    """

    source_monitor_uuid = sgqlc.types.Field(UUID, graphql_name="sourceMonitorUuid")
    """For an eval-monitor-derived issue cluster, the monitor it tracks."""


class ConversationClusteringResult(sgqlc.types.Type):
    """Conversation-clustering panel for one (agent, scope, window):
    enablement state, the space, per-cluster stats, and coverage.
    """

    __schema__ = schema
    __field_names__ = (
        "state",
        "space",
        "clusters",
        "eligible_conversation_count",
        "classified_conversation_count",
        "baseline_metrics",
    )
    state = sgqlc.types.Field(
        sgqlc.types.non_null(ConversationClusteringState), graphql_name="state"
    )
    """Computed enablement state for the (agent, scope)."""

    space = sgqlc.types.Field("ConversationClusteringSpaceType", graphql_name="space")
    """The clustering space; null before opt-in (state OPT_IN)."""

    clusters = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(ConversationClusterStat))),
        graphql_name="clusters",
    )
    """Per-cluster windowed stats incl. the synthetic Uncategorized
    bucket; empty until a taxonomy exists.
    """

    eligible_conversation_count = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="eligibleConversationCount"
    )
    """Conversations in the window eligible for classification. On an
    issue space, this is the M in "N of M conversations carry at least
    one issue."
    """

    classified_conversation_count = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="classifiedConversationCount"
    )
    """Conversations in the window carrying a current-taxonomy cluster
    assignment. Classification runs on a schedule, so the most
    recently completed conversations are normally not classified yet
    and this trails eligibleConversationCount. On an issue space, rule
    evaluation writes no Uncategorized sentinel — a conversation
    matching no rule simply gets no assignment row — so this is
    exactly the N in "N of M conversations carry at least one issue."
    """

    baseline_metrics = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(ConversationClusterMetric))),
        graphql_name="baselineMetrics",
    )
    """The same requested aggregates over every eligible conversation in
    the window, assigned or not — the comparison point for each
    cluster's metrics. Empty when no metrics were requested, before a
    taxonomy exists, or when the window held no conversations.
    """


