class ConversationClusteringSpaceType(sgqlc.types.Type):
    """A configured clustering space for an (agent, scope)."""

    __schema__ = schema
    __field_names__ = (
        "uuid",
        "agent_name",
        "scope_workflow",
        "facet",
        "is_enabled",
        "taxonomy_version",
        "discovery_completed_at",
        "user_guidance",
        "state",
        "config",
        "clusters",
        "runs",
        "classification_watermark",
        "budget_limited",
        "daily_classification_budget",
        "trailing_day_spend",
    )
    uuid = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="uuid")
    """Stable space id."""

    agent_name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentName")
    """Agent (service_name) this space clusters."""

    scope_workflow = sgqlc.types.Field(String, graphql_name="scopeWorkflow")
    """Null = whole agent; else one workflow."""

    facet = sgqlc.types.Field(sgqlc.types.non_null(ClusteringFacet), graphql_name="facet")
    """Which panel tab this space serves; drives lifecycle, config, and
    read cardinality.
    """

    is_enabled = sgqlc.types.Field(sgqlc.types.non_null(Boolean), graphql_name="isEnabled")
    """Whether clustering is active; false means paused (taxonomy
    retained).
    """

    taxonomy_version = sgqlc.types.Field(sgqlc.types.non_null(Int), graphql_name="taxonomyVersion")
    """Current taxonomy version."""

    discovery_completed_at = sgqlc.types.Field(DateTime, graphql_name="discoveryCompletedAt")
    """When the current taxonomy completed discovery; null while still
    discovering. Permanently null on an issue space, which never runs
    discovery — use state, not this field, to decide whether an issue
    space has cards to read.
    """

    user_guidance = sgqlc.types.Field(String, graphql_name="userGuidance")
    """Free-text guidance that steers cluster identity during discovery."""

    state = sgqlc.types.Field(
        sgqlc.types.non_null(ConversationClusteringState), graphql_name="state"
    )
    """Computed enablement state for the (agent, scope)."""

    config = sgqlc.types.Field(sgqlc.types.non_null(ClusteringConfig), graphql_name="config")
    """Discovery and classification settings."""

    clusters = sgqlc.types.Field(
        ConversationClusterConnection,
        graphql_name="clusters",
        args=sgqlc.types.ArgDict(
            (
                ("before", sgqlc.types.Arg(String, graphql_name="before", default=None)),
                ("after", sgqlc.types.Arg(String, graphql_name="after", default=None)),
                ("first", sgqlc.types.Arg(Int, graphql_name="first", default=None)),
                ("last", sgqlc.types.Arg(Int, graphql_name="last", default=None)),
            )
        ),
    )
    """Current-version taxonomy clusters, in display order.

    Arguments:

    * `before` (`String`)None
    * `after` (`String`)None
    * `first` (`Int`)None
    * `last` (`Int`)None
    """

    runs = sgqlc.types.Field(
        ConversationClusteringRunConnection,
        graphql_name="runs",
        args=sgqlc.types.ArgDict(
            (
                ("before", sgqlc.types.Arg(String, graphql_name="before", default=None)),
                ("after", sgqlc.types.Arg(String, graphql_name="after", default=None)),
                ("first", sgqlc.types.Arg(Int, graphql_name="first", default=None)),
                ("last", sgqlc.types.Arg(Int, graphql_name="last", default=None)),
            )
        ),
    )
    """Discovery/classification run history for this space, newest first.

    Arguments:

    * `before` (`String`)None
    * `after` (`String`)None
    * `first` (`Int`)None
    * `last` (`Int`)None
    """

    classification_watermark = sgqlc.types.Field(DateTime, graphql_name="classificationWatermark")
    """Readiness time through which every conversation has been examined
    (the coverage watermark the monitor gate reads); null before the
    first watermark run.
    """

    budget_limited = sgqlc.types.Field(sgqlc.types.non_null(Boolean), graphql_name="budgetLimited")
    """True when the trailing-24h classification spend is at the daily
    budget AND backlog remains — classification is paused by budget,
    not caught up. Scanning resumes oldest-first when budget frees.
    """

    daily_classification_budget = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="dailyClassificationBudget"
    )
    """The space's configured daily classification budget
    (conversations/24h).
    """

    trailing_day_spend = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="trailingDaySpend"
    )
    """Conversations classified over the trailing 24 hours (completed
    runs).
    """


