    trigger = sgqlc.types.Field(EtlRunTrigger, graphql_name="trigger")

    attempt_number = sgqlc.types.Field(sgqlc.types.non_null(Int), graphql_name="attemptNumber")

    run_url = sgqlc.types.Field(String, graphql_name="runUrl")

    error = sgqlc.types.Field(JSONString, graphql_name="error")

    attributes = sgqlc.types.Field(sgqlc.types.non_null(JSONString), graphql_name="attributes")

    job_mcon = sgqlc.types.Field(String, graphql_name="jobMcon")
    """MCON of the job instance this run belongs to. Null when the run's
    instance has not been resolved yet.
    """

    group_global_id = sgqlc.types.Field(String, graphql_name="groupGlobalId")
    """Global ID of the group instance this run was attributed to. Null
    when the run's instance has not been resolved yet.
    """

    is_failure = sgqlc.types.Field(sgqlc.types.non_null(Boolean), graphql_name="isFailure")
    """Whether this run ended in a failure-terminal status."""

    job = sgqlc.types.Field("EtlJobV3", graphql_name="job")
    """The job this run belongs to. When `jobMcon` is set this is that
    exact job instance, so `job.mcon` equals `jobMcon`. For a run
    whose instance has not been resolved (`jobMcon` is null) this
    falls back to one row of the logical job identified by
    `jobGlobalId`, so the run still carries a name — use it for
    display, not as instance identity. Unlike `getEtlJobsV3`, stale
    jobs resolve here. Null when no job row is visible to the caller.
    """


