class PerformanceInsightTicket(sgqlc.types.Type):
    """A ticket (Linear issue / Jira ticket) created from
    cost/performance insights.
    """

    __schema__ = schema
    __field_names__ = (
        "id",
        "provider",
        "identifier",
        "url",
        "source_thread_id",
        "covered_insight_keys",
        "created_by",
        "created_time",
    )
    id = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="id")
    """Linkage identifier."""

    provider = sgqlc.types.Field(
        sgqlc.types.non_null(PerformanceInsightTicketProvider), graphql_name="provider"
    )
    """Ticketing provider the ticket was created in."""

    identifier = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="identifier")
    """Human-readable ticket key shown in the URL (e.g. ENG-123,
    COST-45).
    """

    url = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="url")
    """Web URL of the created ticket."""

    source_thread_id = sgqlc.types.Field(
        sgqlc.types.non_null(String), graphql_name="sourceThreadId"
    )
    """Run that surfaced the insights this ticket covers."""

    covered_insight_keys = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(String))),
        graphql_name="coveredInsightKeys",
    )
    """Keys of all insights this ticket covers, within 'sourceThreadId'
    (a ticket can span several).
    """

    created_by = sgqlc.types.Field("UserInfoOutput", graphql_name="createdBy")
    """Display label for the user who created the ticket. Returns the
    user's email for human users; for agent users, returns a derived
    display label (e.g. ``Agent on <domain>``) — never the agent's
    internal address.
    """

    created_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="createdTime")
    """When the ticket was created."""


class PerformancePageInsightOutput(sgqlc.types.Type):
    """A single insight surfaced on the Performance Page."""

    __schema__ = schema
    __field_names__ = (
        "key",
        "title",
        "headline",
        "category",
        "content",
        "related_mcons",
        "related_warehouses",
        "estimated_savings",
        "estimated_cost",
        "impact",
        "tickets",
    )
    key = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="key")
    """Identifies this insight within the run that produced it, so a
    ticket can be filed against it. Only meaningful alongside that
    run's 'threadId'.
    """

    title = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="title")
    """Full insight title, as a sentence."""

    headline = sgqlc.types.Field(String, graphql_name="headline")
    """Short, scannable version of the title for card display. Null when
    the run did not produce one.
    """

    category = sgqlc.types.Field(PerformanceInsightCategory, graphql_name="category")
    """Finding type of the insight. Null when the insight has no single
    applicable category.
    """

    content = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="content")
    """Insight body."""

    related_mcons = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(String))),
        graphql_name="relatedMcons",
    )
    """MCONs of the catalog objects this insight references."""

    related_warehouses = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(UUID))),
        graphql_name="relatedWarehouses",
    )
    """UUIDs of the warehouses this insight references."""

    estimated_savings = sgqlc.types.Field(EstimatedSavingsOutput, graphql_name="estimatedSavings")
    """Estimated cost saving if the insight's recommendation is acted on.
    Null when the insight has no quantifiable saving.
    """

    estimated_cost = sgqlc.types.Field(EstimatedCostOutput, graphql_name="estimatedCost")
    """Estimated spend on the insight's flagged workload today, priced
    from its observed usage and the warehouse's rates. Distinct from
    'estimatedSavings': acting on the insight reduces this spend by an
    amount that is often not predictable, so label it as estimated
    cost rather than savings. Null when no rate could price the
    workload, and for storage cleanup, where the estimated spend on
    the tables to remove already equals 'estimatedSavings'.
    """

    impact = sgqlc.types.Field(InsightImpactOutput, graphql_name="impact")
    """The insight's headline impact in its native unit (reclaimable
    storage or recurring compute time). Null when the insight has no
    storage- or time-based quantity; the dollar figures are on
    'estimatedSavings' and 'estimatedCost'.
    """

    tickets = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(PerformanceInsightTicket))),
        graphql_name="tickets",
    )
    """Tickets already created for this insight. Empty when none have
    been filed. Tickets are scoped to the run, so a new run starts
    with none.
    """


class PerformancePageInsightsOutput(sgqlc.types.Type):
    """Cost insights surfaced on the Performance Page."""

    __schema__ = schema
    __field_names__ = (
        "is_enabled",
        "disabled_reason",
        "insights",
        "insights_count",
        "thread_id",
        "created_time",
    )
    is_enabled = sgqlc.types.Field(sgqlc.types.non_null(Boolean), graphql_name="isEnabled")
    """Whether cost insights are fully enabled for the caller's account.
    False when the account no longer has access to them, and while it
    has none yet; 'disabledReason' tells the two apart.
    """

    disabled_reason = sgqlc.types.Field(String, graphql_name="disabledReason")
    """When the account has insights it cannot see in full, this shows
    the reason why they are disabled. Null when the account simply has
    none yet.
    """

    insights = sgqlc.types.Field(
        sgqlc.types.non_null(
            sgqlc.types.list_of(sgqlc.types.non_null(PerformancePageInsightOutput))
        ),
        graphql_name="insights",
    )
    """Insights from the latest completed cost-insights run for the
    caller's account, limited to what the account has access to. Empty
    until a run has produced insights.
    """

    insights_count = sgqlc.types.Field(sgqlc.types.non_null(Int), graphql_name="insightsCount")
    """How many insights the latest completed run produced, which can
    exceed the number in 'insights' when the account does not have the
    Performance & Cost agent feature enabled.
    """

    thread_id = sgqlc.types.Field(String, graphql_name="threadId")
    """Identifier of the run that produced these insights. Null when
    insights are unavailable for the caller's account.
    """

    created_time = sgqlc.types.Field(DateTime, graphql_name="createdTime")
    """When the run that produced these insights started. Null when
    insights are unavailable for the caller's account.
    """


