class ScheduleConfigOutput(sgqlc.types.Type):
    __schema__ = schema
    __field_names__ = (
        "schedule_type",
        "interval_minutes",
        "interval_crontab",
        "interval_crontab_day_or",
        "start_time",
        "min_interval_minutes",
        "timezone",
        "is_automatic",
        "dynamic_schedule_mcons",
        "last_trigger_fired_at",
    )
    schedule_type = sgqlc.types.Field(
        sgqlc.types.non_null(ScheduleType), graphql_name="scheduleType"
    )
    """Type of schedule"""

    interval_minutes = sgqlc.types.Field(Int, graphql_name="intervalMinutes")
    """Time interval between job executions, in minutes. For
    schedule_type=dynamic: null/omitted uses the default interval; 0
    means the monitor only runs when triggered, not on a schedule;
    positive values set a custom interval.
    """

    interval_crontab = sgqlc.types.Field(
        sgqlc.types.list_of(String), graphql_name="intervalCrontab"
    )
    """For schedule_type=fixed, one or more cron schedules to determine
    the next execution, each time uses the closest value of all
    schedules
    """

    interval_crontab_day_or = sgqlc.types.Field(Boolean, graphql_name="intervalCrontabDayOr")
    """If true, use default cron behavior and run when day-of-month OR
    day-of-week match. If false, use alternate behavior and run when
    day-of-month AND day-of-week match.
    """

    start_time = sgqlc.types.Field(DateTime, graphql_name="startTime")
    """For schedule_type=fixed, the date the schedule should start"""

    min_interval_minutes = sgqlc.types.Field(Int, graphql_name="minIntervalMinutes")
    """For schedule_type=dynamic, the minimum time interval between job
    executions
    """

    timezone = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="timezone")
    """Timezone for daylight savings and interpreting cron expressions."""

    is_automatic = sgqlc.types.Field(sgqlc.types.non_null(Boolean), graphql_name="isAutomatic")
    """If true, the schedule was automatically generated by Monte Carlo.
    If false, the schedule was configured by the user.
    """

    dynamic_schedule_mcons = sgqlc.types.Field(
        sgqlc.types.list_of(String), graphql_name="dynamicScheduleMcons"
    )
    """Mcons of tables to trigger schedule on update"""

    last_trigger_fired_at = sgqlc.types.Field(DateTime, graphql_name="lastTriggerFiredAt")
    """Last time an external trigger was observed for this schedule
    (table update seen, or job/task completion received), independent
    of whether a run executed.
    """


class ScheduledReportType(sgqlc.types.Type):
    __schema__ = schema
    __field_names__ = (
        "id",
        "name",
        "report_type",
        "time_interval",
        "interval_position",
        "next_execution_time",
        "config",
        "audience_uuids",
        "enabled",
        "disabled_reason",
        "created_by",
    )
    id = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="id")
    """UUID of the scheduled report."""

    name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="name")
    """User-facing display name of the report."""

    report_type = sgqlc.types.Field(sgqlc.types.non_null(ReportType), graphql_name="reportType")
    """Kind of report being scheduled."""

    time_interval = sgqlc.types.Field(
        sgqlc.types.non_null(ReportInterval), graphql_name="timeInterval"
    )
    """Recurrence interval."""

    interval_position = sgqlc.types.Field(Int, graphql_name="intervalPosition")
    """Position within the interval: hour of day (0-23, UTC) for DAY —
    null means Monte Carlo picks the delivery time — weekday
    (1=Mon..7=Sun) for WEEK, day of month (1-31, clamped to month end)
    for MONTH.
    """

    next_execution_time = sgqlc.types.Field(
        sgqlc.types.non_null(DateTime), graphql_name="nextExecutionTime"
    )
    """UTC time of next scheduled delivery."""

    config = sgqlc.types.Field(sgqlc.types.non_null(JSONString), graphql_name="config")
    """Report scope configuration; shape depends on the report type."""

    audience_uuids = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(UUID))),
        graphql_name="audienceUuids",
    )
    """Audience (monitor label) UUIDs the report is delivered to."""

    enabled = sgqlc.types.Field(sgqlc.types.non_null(Boolean), graphql_name="enabled")
    """Whether the report is actively scheduled. False when the account
    no longer has access to this kind of report or when a user
    explicitly disables it.
    """

    disabled_reason = sgqlc.types.Field(String, graphql_name="disabledReason")
    """Why the report is not actively scheduled, or null when it is. Set
    whenever 'enabled' is false: either a user turned the report off,
    or the account no longer has access to this kind of report.
    """

    created_by = sgqlc.types.Field("UserInfoOutput", graphql_name="createdBy")
    """User who created the report."""


