class TokenMetadata(sgqlc.types.Type):
    """Metadata for the API Access Token"""

    __schema__ = schema
    __field_names__ = (
        "id",
        "first_name",
        "last_name",
        "email",
        "creation_time",
        "created_by",
        "expiration_time",
        "comment",
        "is_service_api_token",
        "groups",
    )
    id = sgqlc.types.Field(String, graphql_name="id")
    """Token id"""

    first_name = sgqlc.types.Field(String, graphql_name="firstName")
    """First name for the owner of the token"""

    last_name = sgqlc.types.Field(String, graphql_name="lastName")
    """Last name for the owner of the token"""

    email = sgqlc.types.Field(String, graphql_name="email")
    """Display label for the owner of the token. Returns the user's email
    for human users; for agent users, returns a derived display label
    (e.g. ``Agent on <domain>``) — never the agent's internal address.
    """

    creation_time = sgqlc.types.Field(DateTime, graphql_name="creationTime")
    """When the token was created"""

    created_by = sgqlc.types.Field(String, graphql_name="createdBy")
    """Display label for the user who created the token. Returns the
    user's email for human users; for agent users, returns a derived
    display label (e.g. ``Agent on <domain>``) — never the agent's
    internal address.
    """

    expiration_time = sgqlc.types.Field(DateTime, graphql_name="expirationTime")
    """When the token is set to expire"""

    comment = sgqlc.types.Field(String, graphql_name="comment")
    """Any comments or description for the token"""

    is_service_api_token = sgqlc.types.Field(Boolean, graphql_name="isServiceApiToken")
    """True if this is an account service token; false if it's a personal
    token
    """

    groups = sgqlc.types.Field(sgqlc.types.list_of(String), graphql_name="groups")
    """Names of the groups for the API token (for service API tokens)."""


class ToolCallBlock(sgqlc.types.Type):
    """A tool call — usually extracted from an inline tool_use content
    block, but also synthesized for column-carried tool-call steps
    (Cortex/Genie/OTel/MLflow) whose I/O arrives on the
    tool_call_input/tool_call_output columns.
    """

    __schema__ = schema
    __field_names__ = ("name", "input_json", "output_json", "tool_use_id")
    name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="name")
    """Tool name"""

    input_json = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="inputJson")
    """The tool's input, always as valid JSON: an object/array for tools
    with structured input (inline tool_use calls), or a JSON string
    for tools whose input is raw text (e.g. a SQL string for
    Cortex/Genie SQL tools). Consumers can JSON-decode it
    unconditionally.
    """

    output_json = sgqlc.types.Field(String, graphql_name="outputJson")
    """The tool's output, for tool steps that carry it on the
    tool_call_output column (Cortex/Genie/OTel/MLflow tool steps),
    always as valid JSON: an object/array for structured output, or a
    JSON string for raw text. Null for inline tool_use calls, whose
    output is conveyed on the paired tool-role message. Consumers can
    JSON-decode it unconditionally.
    """

    tool_use_id = sgqlc.types.Field(String, graphql_name="toolUseId")
    """Unique ID for this tool call (if available)"""


