    """Value is inherited from the associated monitor"""

    triage_priority = sgqlc.types.Field(
        sgqlc.types.non_null(TriagePriority), graphql_name="triagePriority"
    )
    """This alert's last known triage verdict. ``HIGH`` / ``MEDIUM`` /
    ``LOW`` are derived from the latest COMPLETED triage run's alert
    confidence and impact, and survive a re-triage in flight — a newer
    PENDING or ERROR row never masks a real prior verdict. ``PENDING``
    only when no triage has ever completed and a run is in progress.
    ``NOT_TRIAGED`` when no run has ever completed and none is in
    progress, or the latest completed row has null/unmapped scores.
    See ``triageState`` for whether a newer run is currently in flight
    independent of this verdict.
    """

    triage_result = sgqlc.types.Field(TriageAgentRunResult, graphql_name="triageResult")
    """Latest completed triage/assessment result for this alert, or null
    if never triaged. Always consistent with ``triagePriority``: non-
    null exactly when ``triagePriority`` is HIGH/MEDIUM/LOW, and null
    when it is PENDING or NOT_TRIAGED.
    """

    triage_state = sgqlc.types.Field(sgqlc.types.non_null(TriageState), graphql_name="triageState")
    """Whether triage has ever run for this alert, and the latest
    attempt's outcome. Independent of ``triagePriority`` — a re-triage
    sitting in ``PENDING`` state can coexist with a real
    ``triagePriority`` verdict from an earlier completed run. Use this
    field to render an in-progress indicator without losing the
    verdict pill. Related to but distinct from
    ``triageResult.status``: that field only exists when
    ``triageResult`` is non-null, so its status is always
    ``COMPLETED``. This field reflects the true latest attempt,
    including one still running or one that failed.
    """

    tsa_analysis_thread_id = sgqlc.types.Field(String, graphql_name="tsaAnalysisThreadId")
    """Thread holding the latest completed troubleshooting analysis for
    this alert, or null if none is recorded. Non-null means TSA output
    exists, so a caller reading a page of alerts can tell which were
    investigated without querying each one. Null covers alerts never
    investigated and those investigated by the trace troubleshooting
    agent.
    """

    status = sgqlc.types.Field(AlertStatus, graphql_name="status")

    tables = sgqlc.types.Field(sgqlc.types.list_of(TableOutput), graphql_name="tables")
    """Tables or views associated with the alert"""

    assets = sgqlc.types.Field(sgqlc.types.list_of(AssetOutput), graphql_name="assets")
    """Assets (MCONs) associated with the alert"""

    audiences = sgqlc.types.Field(sgqlc.types.list_of(AudienceRef), graphql_name="audiences")
    """List of audiences associated with the alert"""

    monitor_tags = sgqlc.types.Field(
        sgqlc.types.list_of(TagKeyValuePairOutput), graphql_name="monitorTags"
    )
    """Monitor tags associated with the alert"""

    monitor_uuids = sgqlc.types.Field(sgqlc.types.list_of(UUID), graphql_name="monitorUuids")
    """UUIDs of the monitor(s) whose events produced this alert. An alert
    can group events from multiple monitors; the list is deduped.
    Empty for alerts with no monitor-backed events (e.g. pipeline
    alerts).
    """

    from_agent_monitor = sgqlc.types.Field(Boolean, graphql_name="fromAgentMonitor")
    """Whether this alert's monitor was created by an agent. True when
    any of the alert's events points at an agent-created monitor.
    Consistent with the `getAlerts` `fromAgentMonitor` filter.
    """

    notification_status = sgqlc.types.Field(
        sgqlc.types.list_of(sgqlc.types.non_null(IncidentNotificationStatusOutput)),
        graphql_name="notificationStatus",
    )
    """Per-incident notification dispatch records — one per
    audience/channel — showing whether and when Monte Carlo sent each
    notification and whether the send was acknowledged.
    """

    invalid_rows = sgqlc.types.Field(String, graphql_name="invalidRows")
    """Number of invalid rows of a breached monitor if available"""

    execution_error = sgqlc.types.Field(JobExecutionException, graphql_name="executionError")
    """For a monitor-execution-error alert: the failed run's error — the
    exception type, its full message, and the SQL that triggered it.
    Null when the alert is not a run failure.
    """

    domains = sgqlc.types.Field(sgqlc.types.list_of(DomainRef), graphql_name="domains")
    """List of domain associated with the alert"""

    comment_count = sgqlc.types.Field(Int, graphql_name="commentCount")
    """Number of user comments associated with the alert"""

    last_comment_text = sgqlc.types.Field(String, graphql_name="lastCommentText")
    """Text of the most recent user comment on the alert"""

    jira_tickets = sgqlc.types.Field(sgqlc.types.list_of("JiraTicket"), graphql_name="jiraTickets")
    """Jira tickets associated with the alert"""

    service_now_incidents = sgqlc.types.Field(
        sgqlc.types.list_of("ServiceNowIncident"), graphql_name="serviceNowIncidents"
    )
    """ServiceNow incidents associated with the alert"""

    opsgenie_incidents = sgqlc.types.Field(
        sgqlc.types.list_of("OpsgenieIncident"), graphql_name="opsgenieIncidents"
    )
    """Opsgenie incidents associated with the alert"""

    datadog_incidents = sgqlc.types.Field(
        sgqlc.types.list_of("DatadogIncident"), graphql_name="datadogIncidents"
    )
    """Datadog incidents associated with the alert"""

    azure_devops_work_items = sgqlc.types.Field(
        sgqlc.types.list_of("AzureDevOpsWorkItem"), graphql_name="azureDevopsWorkItems"
    )
    """Azure DevOps work items associated with the alert"""

    created_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="createdTime")

    updated_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="updatedTime")

    slo_status = sgqlc.types.Field(SloStatus, graphql_name="sloStatus")
    """SLO status of the alert. Null if no SLO policy applies."""

    slo_type = sgqlc.types.Field(SloType, graphql_name="sloType")
    """SLO type applied to the alert (TTA or TTR). Null if no SLO policy
    applies.
    """

    slo_breached_time = sgqlc.types.Field(DateTime, graphql_name="sloBreachedTime")
    """Timestamp when the SLO breaches. Null if no SLO policy applies."""

    feedback = sgqlc.types.Field(AlertStatus, graphql_name="feedback")
    """DEPRECATED. Use status instead"""

    name = sgqlc.types.Field(String, graphql_name="name")
    """DEPRECATED. Use title instead"""

    uuid = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="uuid")
    """DEPRECATED. Use id instead"""

    url = sgqlc.types.Field(String, graphql_name="url")
    """URL of the alert"""

    summary = sgqlc.types.Field(AgentAlertSummary, graphql_name="summary")
    """Summary section for agent alerts — contains a template-based
    headline describing the breach. Null for non-agent alerts.
    """


