class DomainOutputV2(sgqlc.types.Type, NodeWithUUID):
    """Domain configuration"""

    __schema__ = schema
    __field_names__ = (
        "uuid",
        "name",
        "description",
        "obj_assignment_update_time",
        "created_by_email",
        "created_by",
        "domain_tag",
        "assignments",
        "excluded_assignments",
        "tags",
        "excluded_tags",
        "assignments_with_properties",
        "excluded_assignments_with_properties",
        "effective_triage_enabled",
        "triage_enabled_override",
        "tsa_threshold_override",
        "effective_tsa_threshold",
        "effective_auto_apply_enabled",
        "auto_apply_enabled_override",
        "table_counts",
        "monitor_counts",
        "alert_counts",
    )
    uuid = sgqlc.types.Field(UUID, graphql_name="uuid")
    """Domain UUID"""

    name = sgqlc.types.Field(String, graphql_name="name")
    """Domain name"""

    description = sgqlc.types.Field(String, graphql_name="description")
    """Domain description"""

    obj_assignment_update_time = sgqlc.types.Field(DateTime, graphql_name="objAssignmentUpdateTime")
    """Last update time for object assignments"""

    created_by_email = sgqlc.types.Field(String, graphql_name="createdByEmail")
    """Display label for the user who created the domain. Returns the
    user's email for human users; for agent users, returns a derived
    display label (e.g. ``Agent on <domain>``) — never the agent's
    internal address.
    """

    created_by = sgqlc.types.Field(String, graphql_name="createdBy")
    """Domain created by full name (first_name + last_name)"""

    domain_tag = sgqlc.types.Field(String, graphql_name="domainTag")
    """The domain's tag representation"""

    assignments = sgqlc.types.Field(sgqlc.types.list_of(String), graphql_name="assignments")
    """Objects assigned to domain (as MCONs)"""

    excluded_assignments = sgqlc.types.Field(
        sgqlc.types.list_of(String), graphql_name="excludedAssignments"
    )
    """Objects excluded from domain (as MCONs)"""

    tags = sgqlc.types.Field(sgqlc.types.list_of(TagKeyValuePairOutput), graphql_name="tags")
    """Filter by tag key/value pairs for tables."""

    excluded_tags = sgqlc.types.Field(
        sgqlc.types.list_of(TagKeyValuePairOutput), graphql_name="excludedTags"
    )
    """Filter out by tag key/value pairs for tables."""

    assignments_with_properties = sgqlc.types.Field(
        sgqlc.types.list_of(AssignmentWithProperties), graphql_name="assignmentsWithProperties"
    )
    """Objects assigned to domains and their properties"""

    excluded_assignments_with_properties = sgqlc.types.Field(
        sgqlc.types.list_of(AssignmentWithProperties),
        graphql_name="excludedAssignmentsWithProperties",
    )
    """Objects excluded from domains and their properties"""

    effective_triage_enabled = sgqlc.types.Field(
        sgqlc.types.non_null(Boolean), graphql_name="effectiveTriageEnabled"
    )
    """(experimental) Whether alerts in this domain are effectively
    triaged automatically. Combines the account-level automated-triage
    default with the domain's override, matching the automated-triage
    settings page.
    """

    triage_enabled_override = sgqlc.types.Field(Boolean, graphql_name="triageEnabledOverride")
    """(experimental) Raw per-domain automated-triage toggle override.
    Null means the domain inherits the account-level automated-triage
    default; see effectiveTriageEnabled for the resolved value.
    """

    tsa_threshold_override = sgqlc.types.Field(
        TsaAutomationThreshold, graphql_name="tsaThresholdOverride"
    )
    """(experimental) Raw per-domain troubleshooting-agent threshold
    override. Null means the domain inherits the account-level
    threshold.
    """

    effective_tsa_threshold = sgqlc.types.Field(
        TsaAutomationThreshold, graphql_name="effectiveTsaThreshold"
    )
    """(experimental) Effective troubleshooting-agent threshold for this
    domain after applying the override on top of the account-level
    threshold. OFF whenever effectiveTriageEnabled is false.
    """

    effective_auto_apply_enabled = sgqlc.types.Field(
        sgqlc.types.non_null(Boolean), graphql_name="effectiveAutoApplyEnabled"
    )
    """(experimental) Whether monitors assigned to this domain are
    effectively auto-applied when tuning recommends a change. Combines
    the account-level auto-apply setting with the domain's override,
    matching the monitor-tuning auto-apply settings page. False for a
    domain auto-apply cannot reach, which is any domain that is not a
    metadata domain.
    """

    auto_apply_enabled_override = sgqlc.types.Field(
        Boolean, graphql_name="autoApplyEnabledOverride"
    )
    """(experimental) Raw per-domain monitor-tuning auto-apply override.
    Null means the domain inherits the account-level auto-apply
    setting; see effectiveAutoApplyEnabled for the resolved value.
    """

    table_counts = sgqlc.types.Field(DomainTableCounts, graphql_name="tableCounts")
    """Table counts grouped by monitoring status. Selecting `total` on
    its own resolves it from the domain's assignments, which is far
    cheaper on large domains but can read slightly high; select
    `monitored` or `notMonitored` to get all three from the exact per-
    table breakdown. Domains holding more than 100,000 tables are too
    large to break down within the request budget: they return `total`
    with `monitored` and `notMonitored` null, and are skipped
    individually so the other domains on the page still get exact
    counts. A null breakdown is a deterministic answer, not a failure
    — a failed count yields a GraphQL error and no counts at all.
    """

    monitor_counts = sgqlc.types.Field(
        sgqlc.types.list_of(DomainMonitorCounts), graphql_name="monitorCounts"
    )
    """Monitor counts grouped by monitor type"""

    alert_counts = sgqlc.types.Field(DomainAlertCounts, graphql_name="alertCounts")
    """Alert/Incident counts grouped by acknowledgment status"""


