class Finding(sgqlc.types.Type, Node):
    """A finding produced by an autonomous observability agent."""

    __schema__ = schema
    __field_names__ = (
        "created_time",
        "updated_time",
        "uuid",
        "title",
        "summary",
        "detection_time",
        "detail_payload",
        "actions",
        "confidence_score",
        "use_case",
        "criticality_score",
        "suggested_next_steps",
        "budget_credits_consumed",
        "finding_type",
        "agent_type",
        "severity",
        "priority",
        "status",
        "agentic_scope_uuid",
        "agentic_scope",
        "parent_finding_uuid",
        "pipeline_execution_uuid",
        "stage",
        "staged",
        "child_findings_count",
        "feedback_action",
        "feedback_at",
        "feedback_by",
        "feedback_history",
        "related_alerts",
        "related_alerts_count",
        "related_monitors",
        "related_monitors_count",
        "deployed_monitors",
        "deployed_monitors_count",
        "proposed_monitor",
        "estimated_credits",
        "estimated_credits_rollup",
        "related_assets",
        "related_assets_count",
        "tsa_analysis",
    )
    created_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="createdTime")

    updated_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="updatedTime")

    uuid = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="uuid")
    """Public finding identifier."""

    title = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="title")
    """Human-readable title."""

    summary = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="summary")
    """Agent-generated summary."""

    detection_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="detectionTime")
    """When the agent run produced this finding."""

    detail_payload = sgqlc.types.Field(
        sgqlc.types.non_null(JSONString), graphql_name="detailPayload"
    )
    """Type-specific structured data. Schemas are owned by the agent repo
    and validated at write time by the agents themselves.
    """

    actions = sgqlc.types.Field(sgqlc.types.non_null(JSONString), graphql_name="actions")
    """Available actions the user can take on this finding."""

    confidence_score = sgqlc.types.Field(Float, graphql_name="confidenceScore")
    """Agent self-reported confidence in the finding (0–1)."""

    use_case = sgqlc.types.Field(String, graphql_name="useCase")
    """Business use case the finding relates to, e.g. "Finance
    reporting".
    """

    criticality_score = sgqlc.types.Field(Int, graphql_name="criticalityScore")
    """Criticality of the affected asset (0–100)."""

    suggested_next_steps = sgqlc.types.Field(String, graphql_name="suggestedNextSteps")
    """Suggested next steps for the user (plain text / markdown)."""

    budget_credits_consumed = sgqlc.types.Field(Decimal, graphql_name="budgetCreditsConsumed")
    """Credits this finding consumed when produced."""

    finding_type = sgqlc.types.Field(sgqlc.types.non_null(FindingType), graphql_name="findingType")

    agent_type = sgqlc.types.Field(sgqlc.types.non_null(FindingAgentType), graphql_name="agentType")

    severity = sgqlc.types.Field(FindingSeverity, graphql_name="severity")

    priority = sgqlc.types.Field(sgqlc.types.non_null(FindingPriority), graphql_name="priority")
    """Human-escalation axis — applies to all findings. Independent from
    `severity`, which is alarm-specific. Used by notification routing
    to decide whether a finding should page a human.
    """

    status = sgqlc.types.Field(sgqlc.types.non_null(FindingStatus), graphql_name="status")

    agentic_scope_uuid = sgqlc.types.Field(
        sgqlc.types.non_null(UUID), graphql_name="agenticScopeUuid"
    )

    agentic_scope = sgqlc.types.Field(
        sgqlc.types.non_null(AgenticDomainOutput), graphql_name="agenticScope"
    )
    """Domain this finding is scoped to."""

    parent_finding_uuid = sgqlc.types.Field(UUID, graphql_name="parentFindingUuid")

    pipeline_execution_uuid = sgqlc.types.Field(UUID, graphql_name="pipelineExecutionUuid")
    """UUID of the agent run that produced this finding, letting findings
    from one run be correlated. Null when no run is recorded — a
    finding produced outside an agent pipeline, or one written before
    runs were recorded. Do NOT derive a monitoring-plan deeplink from
    this: a plan's identity falls back to its container's own UUID
    when there is no run, so use MonitoringPlan.planUuid (or
    monitoringPlanForMonitor) which already resolves that.
    """

    stage = sgqlc.types.Field(FindingStage, graphql_name="stage")
    """Set when this finding is one phase of a staged monitoring strategy
    (a suggested, ordered monitor rollout for a use case); null
    otherwise — including on the strategy's top-level container. Use
    `staged` to identify the container, which has no stage of its own.
    """

    staged = sgqlc.types.Field(sgqlc.types.non_null(Boolean), graphql_name="staged")
    """Whether this finding is part of a staged monitoring strategy —
    true for both a phase (has a `stage`) and the top-level container
    (no `stage`, but its children are phases). Lets the list
    distinguish a suggested monitoring strategy from a standalone
    monitoring finding. Filterable via `staged`.
    """

    child_findings_count = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="childFindingsCount"
    )
    """How many direct child findings this finding has. On a monitoring-
    plan container it separates a run that produced nothing (0) from
    one whose output is not staged — a container whose children are
    MONITOR_DEPLOYED leaves already deployed its monitors, so it has
    content to show even though `staged` is false.
    """

    feedback_action = sgqlc.types.Field(FindingFeedbackAction, graphql_name="feedbackAction")
    """Latest feedback action on this finding (null if none)."""

    feedback_at = sgqlc.types.Field(DateTime, graphql_name="feedbackAt")
    """When the latest feedback was recorded."""

    feedback_by = sgqlc.types.Field("User", graphql_name="feedbackBy")
    """User who submitted the latest feedback."""

    feedback_history = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(FeedbackEntry))),
        graphql_name="feedbackHistory",
    )
    """Full feedback history (newest first)."""

    related_alerts = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(RelatedAlert))),
        graphql_name="relatedAlerts",
    )

    related_alerts_count = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="relatedAlertsCount"
    )

    related_monitors = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(RelatedMonitor))),
        graphql_name="relatedMonitors",
    )

    related_monitors_count = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="relatedMonitorsCount"
    )

    deployed_monitors = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(DeployedMonitor))),
        graphql_name="deployedMonitors",
    )

    deployed_monitors_count = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="deployedMonitorsCount"
    )

    proposed_monitor = sgqlc.types.Field(ProposedMonitor, graphql_name="proposedMonitor")
    """The monitor this finding proposes to create, with its apply
    lifecycle (pending/in_progress/applied/failed), eligibility, and
    the deployed monitor once applied. Null for findings that are not
    individual monitor proposals.
    """

    estimated_credits = sgqlc.types.Field(EstimatedCredits, graphql_name="estimatedCredits")
    """Expected daily credit consumption for the monitor this finding
    proposes, derived from its staged configuration — the same preview
    shown when creating a monitor directly. Only present on individual
    monitor proposals for accounts on the per-monitor credit
    consumption pricing model; null when no estimate can be computed
    (e.g. an invalid staged configuration). Staged monitors have no
    run history to resolve segment counts from, so segmented
    configurations estimate without the segment multiplier and carry
    an unresolved-segment-count warning.
    """

    estimated_credits_rollup = sgqlc.types.Field(
        EstimatedCreditsRollup, graphql_name="estimatedCreditsRollup"
    )
    """Aggregate credit estimate for a monitoring-plan container — the
    sum across the staged monitors beneath it that are not yet
    applied, i.e. what enabling the rest of it would add per day.
    Present only on `MONITORING_GAP` findings (both a plan's top-level
    container and an individual stage) for accounts on the per-monitor
    credit consumption pricing model; null on monitor proposals
    themselves (use `estimatedCredits`) and on containers with nothing
    left to enable. Aggregates every monitor leaf beneath the finding,
    not just direct children, so a container's total spans its stages.
    Consult the returned counts before rendering: the total is a lower
    bound whenever `nullEstimateCount` or `unresolvedSegmentCount` is
    non-zero, and a plan spanning several containers must be summed
    across them.
    """

    related_assets = sgqlc.types.Field(
        sgqlc.types.non_null(sgqlc.types.list_of(sgqlc.types.non_null(RelatedAsset))),
        graphql_name="relatedAssets",
    )

    related_assets_count = sgqlc.types.Field(
        sgqlc.types.non_null(Int), graphql_name="relatedAssetsCount"
    )

    tsa_analysis = sgqlc.types.Field(TsaAnalysis, graphql_name="tsaAnalysis")
    """TSA analysis for escalated findings with a triggering alert. Null
    when no triggering alert is linked or no TSA run exists.
    """


