class PlatformAgent(sgqlc.types.Type, Node):
    __schema__ = schema
    __field_names__ = (
        "created_time",
        "updated_time",
        "uuid",
        "account",
        "warehouse",
        "agent_type",
        "agent_mcon",
        "agent_name",
        "agent_database",
        "agent_schema",
        "table_prefix",
        "trace_table",
        "schedule",
        "sql_tool_calls_schedule",
        "trace_export_schedule",
        "recommendations_generated_at",
        "display_name",
        "supports_conversation_eval",
        "supports_conversation_clustering",
        "supports_token_metrics",
        "trace_table_mcon",
        "trace_table_ingested",
        "collector_status",
    )
    created_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="createdTime")

    updated_time = sgqlc.types.Field(sgqlc.types.non_null(DateTime), graphql_name="updatedTime")

    uuid = sgqlc.types.Field(sgqlc.types.non_null(UUID), graphql_name="uuid")
    """Unique identifier for this platform agent."""

    account = sgqlc.types.Field(sgqlc.types.non_null(Account), graphql_name="account")

    warehouse = sgqlc.types.Field(Warehouse, graphql_name="warehouse")
    """Warehouse where this agent is defined."""

    agent_type = sgqlc.types.Field(String, graphql_name="agentType")
    """Platform type for this agent (e.g. snowflake)"""

    agent_mcon = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentMcon")
    """Agent MCON:
    MCON++{account}++{warehouse}++agent++{db}:{schema}.{name}
    """

    agent_name = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentName")
    """Agent name on the platform."""

    agent_database = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentDatabase")
    """Platform database containing the agent."""

    agent_schema = sgqlc.types.Field(sgqlc.types.non_null(String), graphql_name="agentSchema")
    """Platform schema containing the agent."""

    table_prefix = sgqlc.types.Field(String, graphql_name="tablePrefix")
    """Trace-table identifier prefix for Databricks-MLflow platform
    agents. For DATABRICKS_MLFLOW_SDK, the SDK writes
    `<table_prefix>_otel_*` managed tables and exposes a
    `<table_prefix>_trace_unified` view; for DATABRICKS_MLFLOW_KA, the
    Knowledge Assistant UI sync writes a single Delta table whose name
    IS the prefix; for DATABRICKS_GENIE, MC's collector writes a
    single Delta table whose name IS the prefix (same shape as KA).
    Null for Snowflake agents.
    """

    trace_table = sgqlc.types.Field("WarehouseTable", graphql_name="traceTable")
    """Real catalogued trace table this Databricks agent reads — carries
    its domain assignment and lineage. Required for Databricks
    (resolved at registration); null for Snowflake agents, and cleared
    if the table is later deleted. SET_NULL so a table deletion drops
    the link, not the agent.
    """

    schedule = sgqlc.types.Field(
        sgqlc.types.non_null(DataCollectorSchedule), graphql_name="schedule"
    )

    sql_tool_calls_schedule = sgqlc.types.Field(
        DataCollectorSchedule, graphql_name="sqlToolCallsSchedule"
    )
    """Schedule for the AGENT_DATA_LINEAGE sweep over this platform
    agent.
    """

    trace_export_schedule = sgqlc.types.Field(
        DataCollectorSchedule, graphql_name="traceExportSchedule"
    )
    """Schedule for the PLATFORM_TRACE_EXPORT job that ships this agent's
    traces as OTLP-JSON to the account's AO ingest bucket (AO-914).
    The export builder resolves its agent through this FK. Written by
    the support enable flow and, on accounts with
    CONFIG_PLATFORM_TRACE_EXPORT_ENABLED set, by the registration hook
    at agent (re-)registration.
    """

    recommendations_generated_at = sgqlc.types.Field(
        DateTime, graphql_name="recommendationsGeneratedAt"
    )
    """Unused. Timestamp when the (removed) recommendation service last
    ran for this platform agent.
    """

    display_name = sgqlc.types.Field(String, graphql_name="displayName")
    """Human-friendly display name for this agent (e.g. a Databricks
    Agent Bricks tile name). Null when unresolved; readers fall back
    to agent_name.
    """

    supports_conversation_eval = sgqlc.types.Field(
        sgqlc.types.non_null(Boolean), graphql_name="supportsConversationEval"
    )
    """Whether conversation-level evaluation monitors can be configured
    for this agent. When false, only span/trace-level eval scopes are
    available.
    """

    supports_conversation_clustering = sgqlc.types.Field(
        sgqlc.types.non_null(Boolean), graphql_name="supportsConversationClustering"
    )
    """Whether conversation clustering can be enabled for this agent —
    gates the Clusters panel and the clustering opt-in.
    """

    supports_token_metrics = sgqlc.types.Field(
        sgqlc.types.non_null(Boolean), graphql_name="supportsTokenMetrics"
    )
    """Whether this agent reports token counts. When false (e.g.
    Databricks Genie, which reports none), token-based metrics compute
    as 0 — hide them rather than read that as real usage.
    """

    trace_table_mcon = sgqlc.types.Field(String, graphql_name="traceTableMcon")
    """MCON of the real catalogued trace table this agent is anchored on,
    for Databricks agents. Carries the agent's domain assignment and
    lineage. Null for Snowflake agents (which have no backing table)
    and for Databricks agents whose trace table has not yet been
    ingested by metadata collection.
    """

    trace_table_ingested = sgqlc.types.Field(
        sgqlc.types.non_null(Boolean), graphql_name="traceTableIngested"
    )
    """Whether this agent's real catalogued trace table is linked yet.
    True for Snowflake agents (no separate trace table) and for
    Databricks agents already anchored on their catalogued table.
    False for a Databricks agent registered before metadata collection
    ingested its trace table — the link is filled automatically on the
    next catalog ingest. The agent is fully operational meanwhile
    (spans collect on its synthetic identity); only the catalog /
    domain / lineage anchoring to the real table is deferred. Use this
    to distinguish a pending Databricks link (False) from a Snowflake
    agent (True), which both report a null traceTableMcon.
    """

    collector_status = sgqlc.types.Field(GenieCollectorStatus, graphql_name="collectorStatus")
    """Run-health of the Monte-Carlo-managed Genie trace collector for
    this agent — its install state, last run outcome, last error, and
    last successful refresh. Null for non-Genie agents (Snowflake /
    Agent Bricks), which have no collector.
    """


